require_once __DIR__ . '/config.php';

$uri = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);
$bd = rtrim(dirname($_SERVER['SCRIPT_NAME']), '/');
if ($bd && $bd !== '/' && strpos($uri, $bd) === 0) $uri = substr($uri, strlen($bd));
$seg = array_values(array_filter(explode('/', trim($uri, '/')), 'strlen'));
if (!empty($seg) && preg_match('/^index\.php$/i', $seg[0])) array_shift($seg);

$page = 'landing'; $slug = ''; $cat = ''; $paged = max(1, intval($_GET['p'] ?? 1)); $q = trim($_GET['q'] ?? '');

if (!empty($seg)) {
    $s0 = $seg[0];
    if ($s0 === 'blog') {
        $page = 'blog'; $i = 1;
        if (isset($seg[$i]) && $seg[$i] !== 'page') { $cat = $seg[$i]; $i++; }
        if (isset($seg[$i], $seg[$i + 1]) && $seg[$i] === 'page') $paged = max(1, intval($seg[$i + 1]));
    } elseif ($s0 === 'post' && isset($seg[1])) { $page = 'post'; $slug = $seg[1]; }
    elseif ($s0 === 'sharing') $page = 'sharing';
    elseif ($s0 === 'about') $page = 'about';
    elseif ($s0 === 'wish') $page = 'wish';
}
if (isset($_GET['page'])) $page = $_GET['page'];
if (isset($_GET['slug'])) $slug = $_GET['slug'];

$pp = 9; $off = ($paged - 1) * $pp;
if ($page === 'post' && $slug) { try { db()->prepare("UPDATE posts SET view_count=view_count+1 WHERE slug=? AND status='published'")->execute([$slug]); } catch (Exception $e) {} }
$cats = get_categories();
$bn = setting('blog_name', BLOG_NAME); $bt = setting('blog_tagline', BLOG_TAGLINE);
$an = setting('author_name', '摸鱼人'); $ab = setting('author_bio', ''); $ar = setting('author_role', '开发者 · 创作者 · 专业摸鱼人'); $icp = setting('icp_filing', '');
