<script>
var wP=1;loadW(1);
function loadW(p){wP=p;fetch('<?=url("api.php")?>?action=wish_list&page='+p).then(r=>r.json()).then(d=>{if(!d.success)return;var g=document.getElementById('wg'),w=d.data.wishes;if(!w.length){g.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:40px"><div style="font-size:40px;opacity:.25;margin-bottom:12px">🐟</div><p style="color:var(--t3)">还没有留言，做第一个吧</p></div>';document.getElementById('wpg').innerHTML='';return;}
g.innerHTML=w.map(function(x,i){var tb=x.wish_type==='wish'?'<span class="wtb wish">⭐ 许愿</span>':'<span class="wtb message">💬 留言</span>';return '<div class="wc glass" style="animation-delay:'+(i*0.04)+'s"><div class="wch"><div class="wav" style="background:'+x.avatar_color+'">'+esc(x.nickname).charAt(0).toUpperCase()+'</div><div style="flex:1;min-width:0"><div style="display:flex;align-items:center;gap:6px"><span class="wnk">'+esc(x.nickname)+'</span>'+tb+'</div><div class="wtm">'+tAgo(x.created_at)+'</div></div></div><div class="wct">'+esc(x.content)+'</div></div>'}).join('');
var pg='';if(d.data.pages>1){if(p>1)pg+='<a href="javascript:loadW('+(p-1)+')">←</a>';for(var i=1;i<=d.data.pages;i++)pg+=i===p?'<span class="cur">'+i+'</span>':'<a href="javascript:loadW('+i+')">'+i+'</a>';if(p<d.data.pages)pg+='<a href="javascript:loadW('+(p+1)+')">→</a>';}document.getElementById('wpg').innerHTML=pg;})}
function postW(){var n=document.getElementById('wn').value.trim(),c=document.getElementById('wc').value.trim(),t=document.querySelector('input[name="wt"]:checked').value;if(!n)return alert('请输入昵称');if(!c)return alert('请输入内容');var fd=new FormData();fd.append('nickname',n);fd.append('content',c);fd.append('wish_type',t);fetch('<?=url("api.php")?>?action=wish_post',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.success){document.getElementById('wc').value='';loadW(1);}else alert(d.error||'失败');});}
function esc(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML;}
function tAgo(dt){var diff=Math.floor((Date.now()-new Date(dt.replace(' ','T')+(dt.indexOf('+')<0?'+08:00':'')).getTime())/1000);if(diff<60)return'刚刚';if(diff<3600)return Math.floor(diff/60)+' 分钟前';if(diff<86400)return Math.floor(diff/3600)+' 小时前';return Math.floor(diff/86400)+' 天前';}
</script><?php break;

default: redirect(url('/')); endswitch;?>
